parameters.jsCode:
const item = $input.item.json;
const candidate = item.researchCandidateName;
const out = (item.output && typeof item.output === 'object') ? item.output : item;
const now = new Date().toISOString();

const news = Array.isArray(out.news)
  ? out.news.filter((entry) => typeof entry === 'string' && entry.trim().length > 0)
  : [];
const club = out.club || null;
const contract = out.contract || null;
const marketValue = out.marketValue || null;
const injuries = out.injuries || null;
const currentSituation = out.currentSituation || null;
const transferLikelihoodNotes = out.transferLikelihoodNotes || null;
const source = out.source || 'Websuche (Quelle nicht spezifiziert)';

let confidence = typeof out.confidence === 'number' ? out.confidence : 0;
if (!Number.isFinite(confidence)) confidence = 0;
confidence = Math.max(0, Math.min(1, confidence));

// Nur mit allen fachlichen Pflichtfeldern (siehe 'Recherche pruefen' in
// due-diligence-subworkflow.json) gilt der Zweig als nicht 'uncertain'.
const hasCoreFacts = Boolean(club) && Boolean(contract) && Boolean(marketValue) && Boolean(injuries) && news.length > 0;
const uncertain = !hasCoreFacts;

const researchResult = {
  candidate,
  club,
  contract,
  marketValue,
  injuries,
  currentSituation,
  transferLikelihoodNotes,
  news,
  source,
  timestamp: now,
  confidence: uncertain ? 0 : confidence,
  uncertain,
  uncertaintyReason: uncertain
    ? 'Websuche konnte nicht alle erforderlichen Angaben (Verein, Vertrag, Marktwert, Verletzungen, News) belastbar ermitteln.'
    : null
};

return [{
  json: {
    ...item,
    researchRuntimeBatchId: item.researchBatchId,
    researchRuntimeCandidate: candidate,
    researchRuntimeStatus: uncertain ? 'uncertain' : 'success',
    researchRuntimePayload: JSON.stringify(researchResult),
    researchRuntimeCompletedAt: now
  }
}];

const current = $input.item.json || {};
const candidate = current.researchCandidateName || 'unbekannter Kandidat';
const reason = (current.error && (current.error.message || current.error)) || 'Recherche-Agent konnte kein Ergebnis liefern.';
const now = new Date().toISOString();

const researchResult = {
  candidate,
  club: null,
  contract: null,
  marketValue: null,
  injuries: null,
  currentSituation: null,
  transferLikelihoodNotes: null,
  news: [],
  source: 'Websuche fehlgeschlagen (keine Quelle verfuegbar)',
  timestamp: now,
  confidence: 0,
  uncertain: true,
  uncertaintyReason: String(reason)
};

return [{
  json: {
    ...current,
    researchRuntimeBatchId: current.researchBatchId,
    researchRuntimeCandidate: candidate,
    researchRuntimeStatus: 'agent_error',
    researchRuntimePayload: JSON.stringify(researchResult),
    researchRuntimeCompletedAt: now
  }
}];
